{
  "process": "Each row represents a single time‑stamped observation of a machine unit during its operation, recording sensor values (temperatures, speeds, torque, tool wear) and the unit’s variant; the unit is first manufactured, then installed, and repeatedly monitored until it either fails or the observation ends.",
  "target_known_at": "the failure event (or the end of the observation window if no failure occurs)",
  "prediction_point": "the latest sensor measurement taken just before the failure (or censoring) event",
  "columns": [
    {
      "name": "Cutter wear [min]",
      "event": "tool wear measurement taken during a routine sensor reading",
      "verdict": "AVAILABLE",
      "confidence": 0.98
    },
    {
      "name": "Moment [Nm]",
      "event": "torque measurement taken during a routine sensor reading",
      "verdict": "AVAILABLE",
      "confidence": 0.98
    },
    {
      "name": "hd_f",
      "event": "failure type determination made when a failure occurs (heat dissipation failure)",
      "verdict": "UNAVAILABLE",
      "confidence": 0.95
    },
    {
      "name": "pw_f",
      "event": "failure type determination made when a failure occurs (power failure)",
      "verdict": "UNAVAILABLE",
      "confidence": 0.95
    },
    {
      "name": "Spindle speed [rpm]",
      "event": "spindle speed measurement taken during a routine sensor reading",
      "verdict": "AVAILABLE",
      "confidence": 0.98
    },
    {
      "name": "Variant",
      "event": "product variant assigned at manufacturing",
      "verdict": "AVAILABLE",
      "confidence": 0.98
    },
    {
      "name": "Operating temp [K]",
      "event": "process temperature measurement taken during a routine sensor reading",
      "verdict": "AVAILABLE",
      "confidence": 0.98
    },
    {
      "name": "os_f",
      "event": "failure type determination made when a failure occurs (overstrain failure)",
      "verdict": "UNAVAILABLE",
      "confidence": 0.95
    },
    {
      "name": "Ambient temp [K]",
      "event": "air temperature measurement taken during a routine sensor reading",
      "verdict": "AVAILABLE",
      "confidence": 0.98
    },
    {
      "name": "tw_f",
      "event": "failure type determination made when a failure occurs (tool wear failure)",
      "verdict": "UNAVAILABLE",
      "confidence": 0.95
    }
  ]
}
